"""Reproduce the accepted three-scene mesh recipe, verifying every generated byte hash."""

import argparse, os
from workspace import ROOT, owned, read_json, digest, atomic_json
from preflight import SPECS, dataset_base, load
from evaluate import free_gpus


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--gpu", type=int, required=True)
    a = p.parse_args()
    if not os.environ.get("CASE1_PROTECTION"):
        raise RuntimeError("Protected runtime required")
    if a.gpu not in free_gpus():
        raise RuntimeError("GPU capacity policy not satisfied")
    recipe = read_json(ROOT / "configs/navmesh-recipe.json")
    name = recipe["profile_id"]
    if not name or any(c not in "abcdefghijklmnopqrstuvwxyz0123456789-" for c in name):
        raise ValueError("Unsafe profile name")
    os.environ["CUDA_VISIBLE_DEVICES"] = str(a.gpu)
    import habitat_sim

    assert habitat_sim.__version__ == recipe["simulator_version"]
    assert recipe["agent"] == {"height": 1.5, "radius": 0.1}
    output = owned(ROOT / "data/derived/navmeshes" / name)
    output.mkdir(parents=True, exist_ok=False)
    scenes = set()
    for ds, spec in SPECS.items():
        scenes.update(
            e["scene_id"]
            for e in load(dataset_base(ds) / spec[1])["episodes"]
            if ds != "rxr" or e["instruction"]["language"] == "en-US"
        )
    result = {
        "schema_version": 1,
        "profile_id": name,
        "simulator_version": habitat_sim.__version__,
        "agent": recipe["agent"],
        "recipe_sha256": digest(ROOT / "configs/navmesh-recipe.json"),
        "construction_script_sha256": digest(__file__),
        "assets": {},
        "status": "REPRODUCED_PENDING_FINAL_RUNTIME_VALIDATION",
    }
    for scene in sorted(scenes):
        glb = ROOT / "data/scene_datasets" / scene
        original = glb.with_suffix(".navmesh")
        mesh = original
        settings_values = None
        if scene in recipe["scenes"]:
            item = recipe["scenes"][scene]
            assert digest(glb) == item["scene_sha256"]
            sc = habitat_sim.SimulatorConfiguration()
            sc.scene_id = str(glb)
            sc.create_renderer = True
            sc.enable_physics = False
            sc.gpu_device_id = 0
            agent = habitat_sim.agent.AgentConfiguration()
            agent.height = 1.5
            agent.radius = 0.1
            sensor = habitat_sim.SensorSpec()
            sensor.uuid = "build_rgb"
            sensor.sensor_type = habitat_sim.SensorType.COLOR
            sensor.resolution = [16, 16]
            sensor.position = [0, 1.25, 0]
            agent.sensor_specifications = [sensor]
            sim = habitat_sim.Simulator(habitat_sim.Configuration(sc, [agent]))
            try:
                settings = habitat_sim.NavMeshSettings()
                settings.set_defaults()
                for key, value in item["settings"].items():
                    setattr(settings, key, value)
                assert (
                    abs(settings.agent_height - 1.5) < 1e-6
                    and abs(settings.agent_radius - 0.1) < 1e-6
                )
                assert sim.recompute_navmesh(sim.pathfinder, settings)
                mesh = output / (glb.stem + ".navmesh")
                assert sim.pathfinder.save_nav_mesh(str(mesh))
                if digest(mesh) != item["expected_navmesh_sha256"]:
                    raise RuntimeError("Native rebuild byte drift: " + scene)
                settings_values = item["settings"]
            finally:
                sim.close()
        result["assets"][scene] = {
            "scene_path": str(glb),
            "scene_sha256": digest(glb),
            "original_navmesh_sha256": digest(original),
            "navmesh_path": str(mesh),
            "navmesh_sha256": digest(mesh),
            "build_settings": settings_values,
        }
    atomic_json(output / "profile.json", result)
    print(str(output / "profile.json"))


if __name__ == "__main__":
    main()
